/**
 * The container generator: {@link ApplicationGraph} → `container.generated.ts` (spec §3.3).
 *
 * ```ts
 * // AUTO-GENERATED by @znight/compiler 0.1.0. Do not edit.
 * import type { ZnightMetadata } from '@znight/core'
 * import { UserService } from '../users/user.service.js'
 *
 * export const __ZNIGHT_METADATA__: ZnightMetadata = {
 *   version: 1,
 *   compiler: '0.1.0',
 *   providers: { ['src/users/user.service.ts#UserService']: { scope: 'singleton', class: UserService, deps: [], factory: () => new UserService() } },
 *   resolutionOrder: ['src/users/user.service.ts#UserService'],
 * }
 * export default __ZNIGHT_METADATA__
 * ```
 *
 * The output only depends on the graph (sorted by canonical identities) and the options, never on
 * the scan or generation order: a full compile and any sequence of incremental compiles produce
 * byte-identical modules. After assembly the module is re-parsed with oxc; a syntax error is a
 * compiler bug reported with the name of the extension that produced the faulty section.
 */
import type { DependencyRef } from '@znight/core'
import type { LoadedExtension } from '../extensions/loader.ts'
import type { ApplicationGraph, InterceptedMethodNode, ProviderNode } from '../graph/types.ts'
import type { Diagnostic, Project } from '../project/index.ts'
import type { Doc } from './doc.ts'
import type { Owner } from './module.ts'

import { ErrorCode, METADATA_VERSION } from '@znight/core'
import { parseSync } from 'oxc-parser'

import { createGenBuilders } from '../extensions/generate.ts'
import { DiagnosticBag, relativePath } from '../project/index.ts'
import { ExtensionGenerateContext, GraphIndex, importNode } from './context.ts'
import { hardline, list, marked } from './doc.ts'
import { primitiveLiteral } from './literal.ts'
import {
  arrowBody,
  bodyKind,
  CORE_OWNER,
  describeOwner,
  InvalidNodeError,
  ModuleBuilder,
  memberAccess,
} from './module.ts'
import { quote } from './syntax.ts'

/** Where the generated code runs: `source` locations are emitted in `serve`/`test` (option `sourceLocations: 'dev'`). */
export type CompileMode = 'build' | 'serve' | 'test'

/** Name of the exported metadata constant. */
export const METADATA_EXPORT = '__ZNIGHT_METADATA__'

/** Header comments of every generated module. */
export function generatedHeader(version: string): string[] {
  return [
    `// AUTO-GENERATED by @znight/compiler ${version}. Do not edit.`,
    '// biome-ignore-all lint: generated file',
    '/* eslint-disable */',
  ]
}

/** Inputs of {@link generateContainer}. */
export interface ContainerInput {
  readonly project: Project
  /** The (pruned) graph. Must be free of errors. */
  readonly graph: ApplicationGraph
  /** Loaded extensions, in generation order (`AnalysisResult.extensions`). */
  readonly extensions: readonly LoadedExtension[]
  readonly mode: CompileMode
  /** `@znight/compiler` version written in the header and `metadata.compiler`. */
  readonly version: string
}

/** Output of {@link generateContainer}. */
export interface ContainerOutput {
  readonly code: string
  /** Problems found while generating (extension failures, import routes, syntax check). */
  readonly diagnostics: readonly Diagnostic[]
}

/** Generates the container module. */
export function generateContainer(input: ContainerInput): ContainerOutput {
  const { project, graph } = input
  const bag = new DiagnosticBag()
  const report = (diagnostic: Diagnostic): void => bag.add(diagnostic)
  const module = new ModuleBuilder(project, report)
  module.names.reserve(METADATA_EXPORT)
  module.names.reserve('d')
  const index = new GraphIndex(graph)
  const stored = new Map(graph.extensions.map(entry => [entry.name, entry.stored]))

  // One context per extension, shared by its custom factories and its section (constants dedupe).
  let currentOwner: Owner = CORE_OWNER
  const contexts = new Map<string, ExtensionGenerateContext>()
  const contextOf = (extension: string): ExtensionGenerateContext => {
    let context = contexts.get(extension)
    if (!context) {
      context = new ExtensionGenerateContext({
        extension,
        module,
        index,
        stored: stored.get(extension) ?? [],
        owner: () => currentOwner,
        report,
      })
      contexts.set(extension, context)
    }
    return context
  }
  const guarded = (owner: Owner, build: () => Doc, fallback: Doc): Doc => {
    const previous = currentOwner
    currentOwner = owner
    try {
      return build()
    } catch (error) {
      report(failure(owner, error))
      return fallback
    } finally {
      currentOwner = previous
    }
  }

  const metadataType = module.routeDoc(
    { specifier: '@znight/core', exportName: 'ZnightMetadata', members: [], typeOnly: true },
    { typeOnly: true, sortKey: '@znight/core#ZnightMetadata' },
  )
  const emitSource =
    project.options.sourceLocations === 'always' ||
    (project.options.sourceLocations === 'dev' && input.mode !== 'build')

  // providers
  const providers = graph.providers.map(provider => {
    const entries: [string, Doc][] = [['scope', quote(provider.scope)]]
    if (provider.kind !== 'provides') {
      entries.push(['class', classDoc(module, provider)])
    }
    entries.push([
      'deps',
      list(
        '[',
        ']',
        provider.deps.map(dep => dependencyDoc(dep.ref)),
      ),
    ])
    entries.push(['factory', factoryDoc(provider, module, contextOf, guarded)])
    if (provider.async) {
      entries.push(['async', 'true'])
    }
    if (provider.interceptors.length > 0) {
      entries.push(['interceptors', interceptorsDoc(provider.interceptors, module)])
    }
    if (provider.dispose !== undefined) {
      entries.push(['dispose', quote(provider.dispose)])
    }
    if (provider.name !== undefined) {
      entries.push(['name', quote(provider.name)])
    }
    if (provider.primary) {
      entries.push(['primary', 'true'])
    }
    if (emitSource) {
      const source = provider.source
      entries.push([
        'source',
        object([
          ['file', quote(sourceFile(project, provider))],
          ['line', String(source.line)],
          ['column', String(source.column)],
        ]),
      ])
    }
    return [`[${quote(provider.token)}]: `, object(entries, true)] as Doc
  })

  const metadata: [string, Doc][] = [
    ['version', String(METADATA_VERSION)],
    ['compiler', quote(input.version)],
    ['providers', list('{', '}', providers, { spaced: true, break: providers.length > 0 })],
    ['resolutionOrder', list('[', ']', graph.resolutionOrder.map(quote), { break: graph.resolutionOrder.length > 0 })],
  ]
  if (graph.aliases.length > 0) {
    metadata.push([
      'aliases',
      list(
        '{',
        '}',
        graph.aliases.map(alias => `[${quote(alias.key)}]: ${quote(alias.token)}`),
        { spaced: true },
      ),
    ])
  }
  if (graph.externals.length > 0) {
    const externals = graph.externals.map(external => {
      const entries: [string, Doc][] = [['token', quote(external.token)]]
      if (external.scope !== 'singleton') {
        entries.push(['scope', quote(external.scope)])
      }
      if (external.providedBy !== undefined) {
        entries.push(['providedBy', quote(external.providedBy)])
      }
      if (external.optional) {
        entries.push(['optional', 'true'])
      }
      return object(entries)
    })
    metadata.push(['externals', list('[', ']', externals, { break: true })])
  }

  // extension sections
  const sections: Doc[] = []
  for (const loaded of input.extensions) {
    const extension = loaded.extension
    if (typeof extension.generate !== 'function') {
      continue
    }
    const owner: Owner = { extension: extension.name, activity: 'generating its metadata section' }
    const context = contextOf(extension.name)
    const section = guarded(
      owner,
      () => {
        const node = extension.generate?.call(extension, context)
        return node === undefined ? '' : module.print(node, owner)
      },
      '',
    )
    if (section !== '') {
      sections.push([`[${quote(extension.name)}]: `, marked(markId(extension.name, 'section'), section)])
    }
  }
  if (sections.length > 0) {
    metadata.push(['extensions', list('{', '}', sections, { spaced: true, break: true })])
  }

  const body: Doc = [
    `export const ${METADATA_EXPORT}: `,
    metadataType,
    ' = ',
    object(metadata, true),
    hardline,
    `export default ${METADATA_EXPORT}`,
  ]
  const rendered = module.render(generatedHeader(input.version), body)
  checkSyntax(rendered.text, rendered.marks, report)
  return { code: rendered.text, diagnostics: bag.toArray() }
}

/**
 * `source.file` of a provider: relative to the root for application files, `<package>/<path in the
 * package>` for package files (independent of symlinks and of the `node_modules` layout).
 */
function sourceFile(project: Project, provider: ProviderNode): string {
  const owner = project.ownerOf(provider.location.file)
  const name = owner.package?.publicName
  if (owner.kind === 'package' && name !== undefined) {
    return `${name}/${relativePath(owner.package.dir, provider.location.file)}`
  }
  return provider.source.file
}

/** `{ key: value, ... }` with plain (format) keys. */
function object(entries: readonly (readonly [string, Doc])[], forceBreak = false): Doc {
  return list(
    '{',
    '}',
    entries.map(([key, value]) => [key, ': ', value]),
    { spaced: true, break: forceBreak },
  )
}

/** Doc of a dependency reference. */
export function dependencyDoc(ref: DependencyRef): Doc {
  if (typeof ref === 'string') {
    return quote(ref)
  }
  if ('multi' in ref) {
    return object([['multi', list('[', ']', ref.multi.map(quote))]])
  }
  if ('lazy' in ref) {
    return object([['lazy', quote(ref.lazy)]])
  }
  return object([
    ['token', quote(ref.token)],
    ['optional', 'true'],
  ])
}

function classDoc(module: ModuleBuilder, provider: ProviderNode): Doc {
  if (!provider.importRoute) {
    throw new Error(`[znight] internal error: provider ${provider.token} has no import route`)
  }
  return module.routeDoc(provider.importRoute, { typeOnly: false, sortKey: provider.classIdentity })
}

function argumentList(from: number, count: number): Doc {
  const args: Doc[] = []
  for (let index = 0; index < count; index++) {
    args.push(`d[${from + index}]`)
  }
  return list('(', ')', args)
}

function factoryDoc(
  provider: ProviderNode,
  module: ModuleBuilder,
  contextOf: (extension: string) => ExtensionGenerateContext,
  guarded: (owner: Owner, build: () => Doc, fallback: Doc) => Doc,
): Doc {
  const factory = provider.factory
  switch (factory.kind) {
    case 'constructor': {
      const cls = classDoc(module, provider)
      return factory.args === 0 ? ['() => new ', cls, '()'] : ['d => new ', cls, argumentList(0, factory.args)]
    }
    case 'method':
      return ['d => d[0]', memberAccess(factory.method), argumentList(1, factory.args)]
    case 'custom': {
      const extension = provider.registeredBy
      const owner: Owner = { extension, activity: `generating the factory of ${provider.displayName}` }
      const doc = guarded(
        owner,
        () => {
          const context = contextOf(extension)
          const builders = createGenBuilders()
          let dParam: unknown
          const arrow = builders.arrow(['d'], d => {
            dParam = d
            const deps = Array.from({ length: factory.args }, (_, index) => builders.code`${d}[${index}]`)
            return factory.generate(context, { cls: importNode(provider.classIdentity, false), deps })
          })
          if (arrow.kind !== 'gen:arrow') {
            throw new Error('[znight] internal error: arrow builder')
          }
          const body = module.print(arrow.body, owner)
          return [usesNode(arrow.body, dParam) ? 'd' : '()', arrowBody(body, bodyKind(arrow.body))]
        },
        '() => undefined',
      )
      return marked(markId(extension, `factory of ${provider.token}`), doc)
    }
  }
}

function interceptorsDoc(methods: readonly InterceptedMethodNode[], module: ModuleBuilder): Doc {
  const owner: Owner = { extension: undefined, activity: 'interceptor options' }
  return list(
    '{',
    '}',
    methods.map(method => [
      `[${quote(method.method)}]: `,
      object([
        ['async', method.async ? 'true' : 'false'],
        [
          'chain',
          list(
            '[',
            ']',
            method.chain.map(link => {
              const entries: [string, Doc][] = [['dep', String(link.dep)]]
              if (link.hasOptions) {
                entries.push(['options', optionsDoc(link.options, module, owner)])
              }
              return object(entries)
            }),
          ),
        ],
      ]),
    ]),
    { spaced: true },
  )
}

function optionsDoc(value: unknown, module: ModuleBuilder, owner: Owner): Doc {
  const primitive = primitiveLiteral(value)
  if (primitive !== undefined) {
    return primitive
  }
  return module.print(createGenBuilders().lit(value as never), owner)
}

/** `true` when `target` (a node object) appears in the tree of `node`. */
function usesNode(node: unknown, target: unknown, seen = new Set<unknown>()): boolean {
  if (node === target) {
    return true
  }
  if (typeof node !== 'object' || node === null || seen.has(node)) {
    return false
  }
  seen.add(node)
  const values = Array.isArray(node) ? node : Object.values(node)
  return values.some(value => usesNode(value, target, seen))
}

function failure(owner: Owner, error: unknown): Diagnostic {
  const message = error instanceof Error ? error.message : String(error)
  return {
    code: ErrorCode.VersionMismatch,
    severity: 'error',
    message:
      error instanceof InvalidNodeError
        ? `${describeOwner(owner)} ${message}`
        : `${describeOwner(owner)} failed: ${message}`,
    hints: [
      owner.extension === undefined
        ? 'This is a bug in @znight/compiler: please report it'
        : 'This is a bug in the compiler extension (or an incompatible version of it)',
    ],
  }
}

/** Re-parses the module; a syntax error is reported naming the section that produced it. */
function checkSyntax(
  code: string,
  marks: ReadonlyMap<string, { readonly start: number; readonly end: number }>,
  report: (diagnostic: Diagnostic) => void,
): void {
  const result = parseSync('container.generated.ts', code, { lang: 'ts', sourceType: 'module' })
  for (const error of result.errors) {
    if (error.severity !== 'Error') {
      continue
    }
    const offset = error.labels[0]?.start ?? 0
    let culprit: { id: string; size: number } | undefined
    for (const [id, range] of marks) {
      if (offset >= range.start && offset <= range.end) {
        const size = range.end - range.start
        if (!culprit || size < culprit.size) {
          culprit = { id, size }
        }
      }
    }
    const extension = culprit ? sectionOwner(culprit.id) : undefined
    report({
      code: ErrorCode.VersionMismatch,
      severity: 'error',
      message: `Internal compiler error: the generated module has a syntax error (${error.message})${
        extension === undefined ? '' : ` in the code produced by compiler extension '${extension}'`
      }`,
      hints: [
        extension === undefined
          ? 'This is a bug in @znight/compiler: please report it'
          : `This is a bug in the compiler extension '${extension}': check its code\`...\` templates`,
      ],
    })
  }
}

/** Id of a marked range of code produced by an extension. */
function markId(extension: string, what: string): string {
  return `${extension}\0${what}`
}

/** Extension name of a mark id. */
function sectionOwner(id: string): string | undefined {
  const separator = id.indexOf('\0')
  return separator === -1 ? undefined : id.slice(0, separator)
}
